import{_ as r,o as e,c as o,ag as l}from"./chunks/framework.QfQ7DfGu.js";const g=JSON.parse('{"title":"LoongArch指令C语言实现","description":"","frontmatter":{"title":"LoongArch指令C语言实现","outline":"deep"},"headers":[],"relativePath":"docs-la/others-la64-insn.md","filePath":"docs-la/others-la64-insn.md"}'),a={name:"docs-la/others-la64-insn.md"};function i(d,t,n,h,c,p){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="loongarch64指令c语言模拟实现" tabindex="-1">LoongArch64指令C语言模拟实现 <a class="header-anchor" href="#loongarch64指令c语言模拟实现" aria-label="Permalink to &quot;LoongArch64指令C语言模拟实现&quot;">​</a></h1><h2 id="la-emu模拟器" tabindex="-1"><strong>LA_EMU模拟器</strong> <a class="header-anchor" href="#la-emu模拟器" aria-label="Permalink to &quot;**LA_EMU模拟器**&quot;">​</a></h2><p>LoongArch64模拟器，支持整型，浮点，向量指令集。能够启动Linux。</p><p>支持的指令集如下所示：</p><table tabindex="0"><thead><tr><th>支持的特性（Features）</th><th>目前状态（Status）</th></tr></thead><tbody><tr><td>Loongarch64 base</td><td>✓</td></tr><tr><td>Loongarch64 privilege</td><td>✓</td></tr><tr><td>FP</td><td>✓</td></tr><tr><td>LSX</td><td>✓</td></tr><tr><td>LASX</td><td>✓</td></tr><tr><td>Timer</td><td>✓</td></tr><tr><td>Serial Port</td><td>✓</td></tr><tr><td>Gdb Server</td><td>✓</td></tr><tr><td>Determined events</td><td>✓</td></tr><tr><td>All SPEC CPU</td><td>✓</td></tr><tr><td>Dynamic ELF</td><td>✗</td></tr><tr><td>Multithread</td><td>✗</td></tr><tr><td>Signal</td><td>✗</td></tr><tr><td>Block Device</td><td>✗</td></tr></tbody></table><p>指令的实现基本都在这里：<a href="https://github.com/LoongsonLab/LA_EMU/blob/master/loongarch64/interpreter.c" target="_blank" rel="noreferrer">interpreter.c</a></p><p>仓库的地址在<a href="https://github.com/LoongsonLab/LA_EMU" target="_blank" rel="noreferrer">这里</a></p><h1 id="loongarch特区态指令的一些说明" tabindex="-1">LoongArch特区态指令的一些说明 <a class="header-anchor" href="#loongarch特区态指令的一些说明" aria-label="Permalink to &quot;LoongArch特区态指令的一些说明&quot;">​</a></h1><p>主要是针对龙架构特权态的进一步说明，用C语言的模拟方式，解释特权态指令，更加的贴切。</p><p>下面是一些内容列表：</p><ul><li><p>状态寄存器。介绍了 LoongArch 架构下包含的所有状态寄存器</p></li><li><p>状态寄存器指令。介绍了 LoongArch 架构下针对状态寄存器的特权态指令</p></li><li><p>配置寄存器指令。介绍了 LoongArch 架构下读取 CPU 配置寄存器的特权态指令</p></li><li><p>缓存指令。介绍了 LoongArch 架构下针对 Cache 操作的特权态指令</p></li><li><p>TLB 指令。介绍了 LoongArch 架构下针对 TLB 操作的特权态指令</p></li><li><p>页表指令。介绍了 LoongArch 架构下用于页表维护的特权态指令</p></li><li><p>例外与异常指令。介绍了 LoongArch 架构下处理例外和异常状态的特权态指令</p></li></ul><ol><li>CSR寄存器</li><li>CSR指令<br> 2.1. CSRRD指令<br> 2.2. CSRWR指令<br> 2.3. CSRXCHG指令</li><li>IOCSR指令<br> 3.1. IOCSRRD指令<br> 3.2. IOCSRWR指令</li><li>CPUCFG 指令</li><li>CACOP 指令</li><li>TLB 与页表指令<br> 6.1. TLB 相关指令<br> 6.2. 页表查找指令<br> 6.3. 应用示例</li><li>ERTN指令</li><li>IDLE指令</li><li>SysCALL指令</li></ol><p>文档的说明在<a href="https://os-kernel-with-loong64-doc.readthedocs.io/en/latest/context/privilege_isa/index.html" target="_blank" rel="noreferrer">这里</a></p><h1 id="loongarch32r指令c语言模拟实现" tabindex="-1">LoongArch32R指令C语言模拟实现 <a class="header-anchor" href="#loongarch32r指令c语言模拟实现" aria-label="Permalink to &quot;LoongArch32R指令C语言模拟实现&quot;">​</a></h1><p>基于NEMU实现的LoongArch32-Reduced模拟器</p><p>本项目基于南京大学的 NEMU 项目，向其中移植了龙芯架构32位精简版的支持，即 LoongArch32-Reduced(以下简称为 LA32R)。</p><p>为了向 LA32R 的开发者、学习者、爱好者以及“龙芯杯”大赛提供一个类似于一生一芯项目中的 difftest 环境，我产生了向 NEMU 中移植<br> LA32R ，之后基于 difftest 框架实现 LA32R difftest 的想法。于是该项目诞生了。</p><p>NEMU 模拟器是一个轻量级的指令集模拟器，运行效果相当于一个单周期CPU。</p><h2 id="实现情况" tabindex="-1">实现情况 <a class="header-anchor" href="#实现情况" aria-label="Permalink to &quot;实现情况&quot;">​</a></h2><p>本项目按照《龙芯架构32位精简版参考手册》实现，目前已经实现了：</p><ul><li>除浮点指令之外的全部指令</li><li>除时钟中断、硬件中断、浮点例外之外的全部中断例外支持</li><li>全部的 CSR 寄存器</li><li>项数可配置的 TLB MMU</li><li>向 difftest 框架提供的各 API</li></ul><p>目前尚未实现、无法实现以及不打算实现的内容：</p><ul><li>Cache：不打算实现</li><li>计时器和定时器：NEMU 无法模拟时钟周期，故无法实现</li><li>各种外设（包括串口）：尚未实现。本项目的最终目的是为了实现 difftest ，故外设支持的优先级靠后</li><li>配套的 AM （裸机运行时环境）：尚未实现。理由同上</li></ul><p>仓库地址在<a href="https://gitee.com/loongsonlab/la32r-nemu" target="_blank" rel="noreferrer">这里</a></p>',24)])])}const L=r(a,[["render",i]]);export{g as __pageData,L as default};
